#!/usr/bin/env python3
"""
Round 98b tiles patch (28 September 2026), beside round98b_culprits.py.

  atlas_insets.py  the conflicts page was looked for as "| CONFLICTS" only,
                   and most PDFs print "| Conflicts": Madagascar, the Western
                   Ghats, the Philippines, the Caribbean and others were read
                   as having no numbered cities. A look-up OpenStreetMap could
                   not answer was kept as "not found" for good (Addis Ababa,
                   Nairobi, Sydney). Both fixed; Natural Earth's populated
                   places are asked where OpenStreetMap finds nothing. Method
                   2: every hotspot is done again on the next run.
  atlas_pdfs.py    also asks the Atlas for PDFs of the four hotspots the map
                   has none for (Indo-Burma, Polynesia-Micronesia,
                   Irano-Anatolian, Tumbes-Choco-Magdalena) and writes what
                   answers to atlas/pdfs_looked_for.json.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/atlas_insets.py': '', 'scripts/atlas_pdfs.py': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists():
        raise SystemExit(f"round98b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.write_bytes(new)
    changed.append(path)
print("round98b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
